
.race-card {
  width: 100%;
  max-width: 680px;
  margin: 6px auto;
  background: var(--c-surface);
  border: 2px solid var(--c-border);
  border-radius: 12px;
  overflow: hidden;
  font-size: 13px;
  box-shadow: 0 3px 12px rgba(43, 45, 66, 0.12);
}

.race-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: linear-gradient(135deg, #1e7a50 0%, #145c3b 100%);
  color: #fff;
  .race-title { font-weight: 800; font-size: 0.9rem; i { margin-right: 6px; } }
  .race-live {
    font-size: 0.72rem;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    i { font-size: 0.5rem; color: #ffd166; animation: pulse 1.2s ease infinite; }
  }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

.race-empty {
  padding: 18px;
  color: var(--c-muted);
  font-style: italic;
  text-align: center;
}

.race-row {
  display: flex;
  gap: 14px;
  padding: 14px 14px 6px;
  .race-stat {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    .stat-label { font-size: 0.68rem; color: var(--c-muted); }
    .stat-rank, .stat-dist {
      font-family: var(--font-num);
      font-size: 1.6rem;
      font-weight: 800;
      color: var(--c-primary-dark);
      small { font-size: 0.75rem; font-weight: 400; color: var(--c-muted); margin-left: 3px; }
    }
  }
}

.race-progress {
  margin: 8px 14px;
  height: 8px;
  border-radius: 6px;
  background: var(--c-track);
  overflow: hidden;
  .race-bar {
    height: 100%;
    border-radius: 6px;
    background: linear-gradient(90deg, var(--c-primary), var(--c-primary-dark));
    transition: width 0.3s ease;
  }
}

.race-adv {
  padding: 10px 14px;
  border-top: 1px solid var(--c-border);
  .adv-label, .top3-label {
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--c-primary-dark);
    i { margin-right: 5px; color: var(--c-warning); }
  }
  .adv-chips {
    display: flex;
    gap: 6px;
    margin-top: 6px;
    flex-wrap: wrap;
  }
  .adv-chip {
    font-family: var(--font-num);
    font-size: 0.78rem;
    font-weight: 700;
    padding: 3px 10px;
    border-radius: 8px;
    &.pos { background: #e6f5ef; color: #1f6e42; }
    &.neg { background: #fbe9e4; color: #c0463f; }
    &.neu { background: var(--c-track); color: var(--c-muted); }
  }
  .adv-total {
    margin-top: 8px;
    font-size: 0.9rem;
    font-weight: 800;
    &.pos { color: #1f6e42; }
    &.neg { color: #c0463f; }
    &.neu { color: var(--c-muted); }
  }
}

.race-top3 {
  padding: 10px 14px 14px;
  border-top: 1px solid var(--c-border);
  .top3-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-top: 8px;
  }
  .top3-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 7px 12px;
    border-radius: 10px;
    &.medal-1 { background: linear-gradient(135deg, #fdf3d0, #f5e6b8); border: 1px solid #e4c76a; }
    &.medal-2 { background: linear-gradient(135deg, #ececec, #e0e0e0); border: 1px solid #c9c9c9; }
    &.medal-3 { background: linear-gradient(135deg, #f6e3d5, #efd5c0); border: 1px solid #dfb08c; }
    .top3-medal {
      width: 22px;
      height: 22px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: var(--font-num);
      font-size: 0.72rem;
      font-weight: 800;
      color: #fff;
      background: #c9a227;
      &.medal-2 + & { background: #9e9e9e; }
      &.medal-3 + & { background: #c47a3d; }
    }
    .top3-name { font-weight: 700; color: #3d3d3a; }
  }
}
